#!/usr/bin/env bash
set -euo pipefail

# Materialize symbolic and code domain datasets from manifest.
# Requires: manifests generated by redistribute_manifest_v1.4.sh

timestamp=$(date +%Y%m%d_%H%M%S)
manifest_timestamp="${1:?Usage: $0 <manifest_timestamp>}"
query_types=(ate cate jate)

log_dir="./data_generation/generated_datasets/v1.4/.logs"
mkdir -p "${log_dir}"

echo "=== v1.4 Symbolic/Code Materialization ==="
echo "Run timestamp: ${timestamp}"
echo "Manifest timestamp: ${manifest_timestamp}"

python3 -m data_generation.redistribute_materialize \
    --run_timestamp "${timestamp}" \
    --manifest_timestamp "${manifest_timestamp}" \
    --query_types "${query_types[@]}" \
    --domains symbolic code \
    2>&1 | tee "${log_dir}/${timestamp}-materialize.log"

echo ""
echo "=== Materialization complete ==="
